def main():
    vocabulary=json.loads(VOCAB_PATH.read_text(encoding="utf-8")); phrase_root=json.loads(PHRASE_PATH.read_text(encoding="utf-8")); translations=phrase_root.setdefault("translations",{})
    rows=[x for x in vocabulary if int(x.get("level",0))==3][900:950]; expected={str(x["word"]).casefold() for x in rows}; assert set(EN)&expected==expected; assert all(set(values)==expected for values in LOCALIZED.values())
    changed=0
    for item in rows:
        word=str(item["word"]).casefold(); ex=translations.setdefault(f"builtin:{item['id']}",{}).setdefault("example",{})
        for lang,value in (("en",EN[word]),("ja",JA[word]),*((lang,LOCALIZED[lang][word]) for lang in LOCALIZED)):
            if ex.get(lang)!=value: ex[lang]=value; changed+=1
    PHRASE_PATH.write_text(json.dumps(phrase_root,ensure_ascii=False,indent=1)+"\n",encoding="utf-8")
    print(f"reviewed multilingual examples 700+ 901-950: {len(rows)} terms, {changed} fields")
if __name__=="__main__": main()
